draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // six hundred
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H / 2 - 20);
  ctx.lineTo(W / 2 - 100, H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H / 2);
  ctx.lineTo(W / 2 - 70, H / 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W / 2 - 40, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 40, H / 2 - 20);
  ctx.lineTo(W / 2 - 40, H / 2 + 20);
  ctx.stroke();

  // thirty
  ctx.beginPath();
  ctx.arc(W / 2 + 50, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 50, H / 2 - 20);
  ctx.lineTo(W / 2 + 50, H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 50, H / 2);
  ctx.lineTo(W / 2 + 80, H / 2);
  ctx.stroke();

  ctx.save();
  ctx.translate(W / 2 + 110, H / 2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.arc(0, 0, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
